const b = $json.body || {};
const required = ['entity_type','entity_id','recipient_email'];
for (const k of required) { if (!b[k]) throw new Error(`${k} is required`); }
const allowed = new Set(['lead','customer','guest','contact']);
if (!allowed.has(b.entity_type)) throw new Error('entity_type must be lead|customer|guest|contact');
const intentLabel = {
  introduction: 'Open a real conversation. Earn a reply, do not pitch hard.',
  check_in: 'Casual touch-base referencing what they recently shipped or wrote.',
  podcast_invite: 'Invite them as a guest. Be specific about the angle and why them.',
  follow_up: 'Follow up on a prior thread.',
}[b.intent || 'introduction'] || 'Open a real conversation.';
const voice = b.voice_rules ? `VOICE RULES (follow exactly):\n${b.voice_rules}\n\n` : '';
const ctx = [
  `Recipient name: ${b.recipient_name || '(unknown)'}`,
  `Recipient title: ${b.recipient_title || '(unknown)'}`,
  `Recipient company: ${b.recipient_company || '(unknown)'}`,
  b.linkedin_url ? `LinkedIn: ${b.linkedin_url}` : null,
  '',
  b.context || '(no extra context provided)',
].filter(x => x !== null).join('\n');
const userMsg = `${voice}INTENT: ${intentLabel}\n\nRESEARCH + CONTEXT:\n${ctx}\n\nRULES: Ground every specific claim (company facts, numbers, events, what they said) only in the RESEARCH above. Never invent specifics about them or their company. If shared history is noted, open as a continuation, not a cold intro. One concrete, true opening line. No "I hope this finds you well", no flattery. End with one clear, low-friction ask.\n\nReturn ONLY a JSON object {"subject": string, "body": string}. No preamble, no markdown fence.`;
return [{ json: {
  entity_type: b.entity_type, entity_id: b.entity_id, recipient_email: b.recipient_email,
  recipient_name: b.recipient_name || null,
  prompt: userMsg,
} }];

const blocks = $json.content || [];
const text = blocks.map(b => b.text || '').join('').trim();
const cleaned = text.replace(/```json\s*|\s*```/g, '').trim();
let parsed = null;
try {
  const a = cleaned.indexOf('{');
  const b = cleaned.lastIndexOf('}');
  parsed = JSON.parse(cleaned.slice(a, b + 1));
} catch (e) { throw new Error('Sonnet returned non-JSON: ' + text.slice(0, 200)); }
if (!parsed.subject || !parsed.body) throw new Error('Missing subject or body');
const src = $('Build Prompt').item.json;
return [{ json: {
  entity_type: src.entity_type,
  entity_id: src.entity_id,
  recipient_email: src.recipient_email,
  subject: parsed.subject,
  body: parsed.body,
} }];
